package regression

// Fix-verification snapshots (2026-11 audit, wave F): renders the module-level
// fixed frames into audit/screenshots/fix-verify/ for visual self-check
// (read_image). Run explicitly:
//
//	go test ./internal/regression -run TestFixVerifySnapshots -count=1
//
// Covers UX-02 (900×600 + default-window approval/dock height budget) and UD-01
// (first-launch single primary). The real-assembly US-01/RG-02 frames are
// generated by internal/ui/uimodtest's fix-verify snapshot test.

import (
	"image/png"
	"os"
	"path/filepath"
	"testing"

	"github.com/egoist/mygo/ui"

	"github.com/zeokeel/zeokeel/internal/contracts"
	"github.com/zeokeel/zeokeel/internal/modules/appinfo"
	homeui "github.com/zeokeel/zeokeel/internal/ui/home"
	sessionui "github.com/zeokeel/zeokeel/internal/ui/session"
	sidebarui "github.com/zeokeel/zeokeel/internal/ui/sidebar"
	toastsui "github.com/zeokeel/zeokeel/internal/ui/toasts"
)

const fixVerifyDir = "../../audit/screenshots/fix-verify"

func saveFixFrame(t *testing.T, tester *ui.Tester, name string) {
	t.Helper()
	if err := os.MkdirAll(fixVerifyDir, 0o755); err != nil {
		t.Fatalf("mkdir fix-verify: %v", err)
	}
	path := filepath.Join(fixVerifyDir, name)
	file, err := os.Create(path)
	if err != nil {
		t.Fatalf("create %s: %v", path, err)
	}
	defer file.Close()
	if err := png.Encode(file, tester.Image()); err != nil {
		t.Fatalf("encode %s: %v", path, err)
	}
	t.Logf("fix-verify frame saved: %s", path)
}

// TestFixVerifySnapshots renders the UX-02 and UD-01 fixed frames.
func TestFixVerifySnapshots(t *testing.T) {
	// UX-02: 900×600 minimum window with the full dock stack — the composer and
	// approval footer stay inside the window, the transcript keeps height.
	h, _ := newGeoHarness(t)
	minTester := h.tester(900, 600)
	minTester.Frame()
	minTester.Frame()
	saveFixFrame(t, minTester, "ux02-min-window-900x600.png")

	h2, _ := newGeoHarness(t)
	defaultTester := h2.tester(1512, 944)
	defaultTester.Frame()
	defaultTester.Frame()
	saveFixFrame(t, defaultTester, "ux02-default-window-1512x944.png")

	// UD-01: first-launch landing (zero sessions) keeps a single accent primary.
	landing := newBareHarness(t)
	landing.ui.SetKernelContext(landing.ctx)
	provide(t, landing.ctx, contracts.KeyChat, contracts.ChatService(newFakeChat()))
	provide(t, landing.ctx, contracts.KeyNotifier, contracts.Notifier(landing.ui.Notifier()))
	activate(t, landing.ctx, sessionui.Module(), sessionui.Config{})
	activate(t, landing.ctx, toastsui.Module(), toastsui.Config{})
	activate(t, landing.ctx, appinfo.Module(), appinfo.Config{
		Name: "ZeoKeel", Version: "0.1.0", Commit: "test", BuildTime: "2026-01-01T00:00:00Z",
	})
	activate(t, landing.ctx, homeui.Module(), homeui.Config{})
	activate(t, landing.ctx, sidebarui.Module(), sidebarui.Config{})
	landingTester := landing.tester(1280, 800)
	landingTester.Frame()
	if err := landing.ui.Navigator().Push("home"); err != nil {
		t.Fatalf("Push(home): %v", err)
	}
	landingTester.Frame()
	landingTester.Frame()
	saveFixFrame(t, landingTester, "ud01-landing-single-primary.png")
}
